package com.strmr.tv.api

import com.strmr.tv.library.ProfileDataContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonObject

// The player's extras: seek-preview thumbnails (`/api/video/thumbnails/...`, generated by the
// server or fetched from Seekr) and intro / recap / credits ranges (`/api/video/segments`).

@Serializable
data class VideoThumbnailStatus(
    val key: String? = null,
    /** `pending`, `generating`, `ready`, `failed` or `disabled`. */
    val status: String = "",
    val thumbnails: List<Item>? = null,
) {
    @Serializable
    data class Item(val timeSec: Double, val url: String)
}

/** What the start request tells the server about the stream (Seekr lookup, HDR tone mapping). */
data class ThumbnailStartOptions(
    val seekrOnly: Boolean,
    val imdbId: String?,
    val tmdbId: String?,
    /** `movie` or `episode`. */
    val mediaType: String,
    val season: Int?,
    val episode: Int?,
    val hdr: Boolean,
    val dolbyVision: Boolean,
)

suspend fun ApiClient.videoThumbnailsStatus(path:String,expected:Long):VideoThumbnailStatus=
    thumbnails("GET","/api/video/thumbnails/status",mapOf("path" to path),expected)

suspend fun ApiClient.startVideoThumbnails(path: String, durationSec: Double, options: ThumbnailStartOptions,expected:Long): VideoThumbnailStatus {
    val items = buildList {
        add("path" to path)
        add("duration" to "%.2f".format(java.util.Locale.ROOT, durationSec))
        add("interval" to "60")
        if (options.hdr) add("hdr" to "1")
        if (options.dolbyVision) add("dv" to "1")
        if (options.seekrOnly) add("seekrOnly" to "1")
        options.imdbId?.let { add("imdbId" to it) }
        options.tmdbId?.let { add("tmdbId" to it) }
        add("mediaType" to options.mediaType)
        options.season?.let { add("season" to it.toString()) }
        options.episode?.let { add("episode" to it.toString()) }
    }
    return thumbnails("POST","/api/video/thumbnails/start",items.toMap(),expected)
}

private suspend fun ApiClient.thumbnails(method:String,path:String,query:Map<String,String>,expected:Long):VideoThumbnailStatus {
    val profile=inContext(expected){profileId}
    return send(method,path,query+("profileId" to profile),promptOnLock=false,timeoutMs=60_000,expectedContext=expected)
}

/** A frame URL normalized by the original player image transport, preserving its query. */
fun ApiClient.thumbnailImageUrl(raw:String,access:ThumbnailImageAccess):String?=access.image(raw)?.url

@Serializable
private data class ServerSettings(val playback: Playback? = null) {
    @Serializable
    data class Playback(val thumbnails: Thumbnails? = null)

    @Serializable
    data class Thumbnails(val enabled: Boolean? = null)
}

/** Whether the server admin turned seek-preview thumbnails on (`playback.thumbnails.enabled`). */
suspend fun ApiClient.previewThumbnailsEnabled(expected:Long):Boolean {
    val profile=inContext(expected){profileId}
    return try {send<ServerSettings>("GET","/api/settings",mapOf("profileId" to profile),promptOnLock=false,timeoutMs=10_000,expectedContext=expected).playback?.thumbnails?.enabled ?: false}
    catch(error:kotlinx.coroutines.CancellationException){throw error}catch(_:Exception){false}
}

/** One skippable range, in seconds. */
@Serializable
data class SkipSegment(
    /** `intro`, `recap`, `outro` or `preview`. */
    val type: String,
    val start: Double,
    val end: Double,
)

@Serializable
private data class SkipSegmentsResponse(val segments: List<SkipSegment>? = null)

suspend fun ApiClient.skipSegments(body: JsonObject, expected: Long = ProfileDataContext.current): List<SkipSegment> =
    send<SkipSegmentsResponse>("POST", "/api/video/segments", preparationQuery(expected), body = body, promptOnLock = false, expectedContext = expected).segments.orEmpty()

/** A container chapter of the playing file, as the server's ffprobe read it (`/api/video/metadata`). */
@Serializable
data class VideoChapter(val title: String = "", val start: Double, val end: Double = 0.0)

@Serializable
private data class VideoChaptersResponse(val chapters: List<VideoChapter>? = null)

/**
 * The file's chapters (ExoPlayer surfaces none), for `/api/video/segments` to read credits
 * from chapter names as the Expo player's do. The server caches the probe per path.
 */
suspend fun ApiClient.videoChapters(path: String, expected: Long = ProfileDataContext.current): List<VideoChapter> =
    send<VideoChaptersResponse>("GET", "/api/video/metadata", preparationQuery(expected, mapOf("path" to path)),
                                promptOnLock = false, timeoutMs = 20_000, expectedContext = expected).chapters.orEmpty()
